-- ============================================================\n-- YatraSetu — local_experiences Seed Dataset\n-- Total Community Experiences: 25\n-- ============================================================\n\nUSE yatrasetu;\n\nCREATE TABLE IF NOT EXISTS local_experiences (\n    id                          INT AUTO_INCREMENT PRIMARY KEY,\n    destination_id              INT NOT NULL,\n    title                       VARCHAR(150) NOT NULL,\n    experience_type             VARCHAR(50) NOT NULL,\n    description                 TEXT,\n    duration_minutes            INT DEFAULT 90,\n    price_inr                   INT DEFAULT 0,\n    booking_type                VARCHAR(30) DEFAULT 'walk_in',\n    local_partner               VARCHAR(150),\n    community_revenue_pct       INT DEFAULT 100,\n    best_time                   VARCHAR(50),\n    FOREIGN KEY (destination_id) REFERENCES destinations(id) ON DELETE CASCADE,\n    INDEX idx_exp_dest (destination_id),\n    INDEX idx_exp_type (experience_type)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\nINSERT INTO local_experiences (\n    destination_id, title, experience_type, description,\n    duration_minutes, price_inr, booking_type, local_partner,\n    community_revenue_pct, best_time\n) VALUES\n(1, 'Senchal High-Altitude Dawn Birding & Butter Tea', 'nature_walk', 'Pre-dawn high-altitude birding walk with certified local naturalist guides following the sunrise, concluding with hot butter tea and momos at a village cooperative stall.', 90, 350, 'walk_in', 'Senchal Forest Guides & Tea Cooperative', 100, 'Dawn (05:00 - 06:30)'),\n(2, 'Gorkha Handloom Weaving & Woolen Knitwear Workshop', 'craft_workshop', 'Interactive demonstration of traditional wooden handloom weaving and mountain wool spinning by local Gorkha artisan women.', 60, 200, 'walk_in', 'Gorkha Women Handloom Guild', 95, 'Morning (10:00 - 12:00)'),\n(3, 'Heritage Colonial Tea Salon & Literary History Walk', 'cultural', 'Guided walking tour through Darjeelings 19th-century colonial bookshops, Oxford Bookstore archives, and traditional Himalayan bakeries.', 75, 250, 'walk_in', 'Darjeeling Heritage Walkers Guild', 90, 'Afternoon (15:00 - 17:00)'),\n(4, 'Steam Locomotive Heritage Shed & Engine Driver Stories', 'heritage', 'Behind-the-scenes visit to the vintage 1881 steam locomotive loco shed with retired railway foremen sharing tales of mountain track engineering.', 60, 300, 'prior_booking', 'DHR Heritage Railway Workers Union', 85, 'Morning (09:30 - 11:00)'),\n(5, 'Everest Expedition Equipment & Climbing Knot Masterclass', 'adventure', 'Hands-on alpine knot tying, safety harness rigging, and Everest expedition equipment handling led by certified Sherpa instructors.', 90, 400, 'walk_in', 'Sherpa Alpine Instructors Association', 90, 'Morning (10:00 - 12:00)'),\n(6, 'High-Altitude Wildlife Conservation & Red Panda Habitat Talk', 'nature_walk', 'Guided naturalist walkthrough exploring captive breeding and habitat preservation for endangered Red Pandas and Snow Leopards.', 75, 250, 'walk_in', 'Himalayan Wildlife Naturalist Forum', 100, 'Morning (10:00 - 11:30)'),\n(7, 'Buddhist Evening Drumming Chant & Sunset Meditation', 'spiritual', 'Join resident Buddhist monks for rhythmic Uchiwadaiko (peace drum) chanting and silent sunset meditation overlooking the valley.', 60, 0, 'free_community', 'Nipponzan Myohoji Peace Society', 100, 'Sunset (16:30 - 17:30)'),\n(8, 'Tukvar Valley Tea Garden Terracing & River Descent Trail', 'nature_walk', 'Guided walking trail from the lower Tukvar ropeway terminal down to the Rangeet river valley through century-old tea terraces.', 120, 500, 'prior_booking', 'Tukvar Valley Village Guides', 100, 'Morning (10:30 - 12:30)'),\n(9, 'First Flush Orthodox Tea Tasting & Plucking Workshop', 'tea_tasting', 'Hands-on two leaves and a bud harvesting directly with resident tea pickers, followed by factory tasting of Muscatel and White Darjeeling teas.', 90, 450, 'walk_in', 'Happy Valley Workers Cooperative', 85, 'Morning (09:30 - 11:30)'),\n(10, 'Tibetan Thangka Painting & Sacred Script Calligraphy', 'craft_workshop', 'Learn traditional Tibetan mineral pigment grinding and sacred scroll painting under the direct mentorship of a resident master artist.', 90, 500, 'prior_booking', 'Tibetan Refugee Self-Help Centre', 100, 'Afternoon (14:00 - 16:00)'),\n(11, 'Monastic Morning Chanting & Butter Sculpting Observation', 'spiritual', 'Observe the atmospheric morning assembly of 200+ monks chanting deep sutras and crafting intricate colored yak-butter sacrificial sculptures.', 60, 0, 'free_community', 'Drukpa Kagyud Monastic Trust', 100, 'Early Morning (06:00 - 07:30)'),\n(12, 'Bhutia Tribal Heritage Homestyle Lunch & Folklore', 'culinary', 'Home-cooked traditional meal of fermented spinach (Gundruk), millet bread (Phale), and steaming Tingmo in a Bhutia village family home.', 75, 350, 'prior_booking', 'Bhutia Busty Community Kitchen', 100, 'Lunchtime (12:30 - 14:00)'),\n(13, 'Organic Mountain Orange Juice Tasting & Waterfall Botany Walk', 'nature_walk', 'Sample freshly hand-pressed Darjeeling mandarin orange juice while discovering wild ferns and Himalayan orchid species with valley farmers.', 60, 200, 'walk_in', 'Barbotey Valley Farmers Collective', 100, 'Morning (11:00 - 12:30)'),\n(14, 'Ancient Palm-Leaf Scripture Archival Tour & Tibetan Incense', 'cultural', 'Exclusive visit to the 1850 monastic library holding ancient Buddhist manuscripts and handmade medicinal herbal incense rolling.', 60, 150, 'walk_in', 'Yiga Choeling Archival Society', 100, 'Morning (09:00 - 10:30)'),\n(15, 'Beginner Natural Rock Climbing & Rappelling Workshop', 'adventure', 'Certified climbing safety instruction, harness rigging, and hands-on natural rock wall climbing where Everest mountaineers first trained.', 90, 600, 'walk_in', 'Sherpa Adventure Guides Guild', 95, 'Morning (10:00 - 12:00)'),\n(16, 'Pine Canopy Meditation & Sacred Hilltop Lake Trek', 'nature_walk', 'Silent meditative walk through towering silver firs up to the sacred mountaintop lake ringed by fluttering prayer flags. 100% of admission funds the village school.', 120, 200, 'walk_in', 'Lamahatta Village Eco-Tourism Committee', 100, 'Morning (09:00 - 11:30)'),\n(17, 'Colonial Bungalow Architectural Trail & Rare Orchid Nursery', 'heritage', 'Walk through 1900s British stone heritage bungalows, followed by a visit to the century-old Takdah Orchid Centre housing endangered species.', 90, 300, 'walk_in', 'Takdah Heritage Youth Forum', 100, 'Morning (10:00 - 12:00)'),\n(18, 'Organic Orange Blossom Honey & Homestead Farmstay Experience', 'homestay', 'Visit organic village permaculture farms, taste pure raw orange blossom honey, and enjoy a wood-fired farm-to-table lunch.', 120, 500, 'prior_booking', 'Tinchuley WWF Model Eco Cooperative', 100, 'Lunchtime (11:30 - 14:00)'),\n(19, 'Senchal Sanctuary Red Panda Conservation & Birding Walk', 'nature_walk', 'Explore virgin rhododendron forests with indigenous village trackers to spot rare mountain birds, barking deer, and signs of red pandas.', 150, 750, 'prior_booking', 'Chatakpur Eco-Development Committee', 100, 'Dawn (05:30 - 08:30)'),\n(20, 'Century-Old Fireplace Tea Salon & Artisan Rolling Workshop', 'tea_tasting', 'Learn artisanal hand-rolling of tea leaves and enjoy hot private-blend estate tea by an authentic 1862 Victorian stone fireplace.', 90, 600, 'prior_booking', 'Singtom Estate Workers Heritage Trust', 85, 'Afternoon (14:00 - 16:00)'),\n(21, 'Rungdung River Valley Bamboo & Hornbill Birding Trail', 'nature_walk', 'River basin forest walk seeking Rufous-necked Hornbills followed by seasonal bamboo shoot pickle tasting with resident families.', 120, 400, 'walk_in', 'Rangaroon Community Ecotourism Network', 100, 'Morning (08:30 - 11:00)'),\n(22, 'Indigenous Lepcha Folklore, Flute Music & Herbal Tea Gathering', 'cultural', 'Evening gathering around a hearth listening to indigenous Lepcha mythology, traditional bamboo flute tunes, and sipping wild-foraged herbal infusions.', 90, 300, 'prior_booking', 'Lepcha Indigenous Heritage Society', 100, 'Evening (17:00 - 18:30)'),\n(23, 'Local Boatmen Rowing & Organic Cardamom Farm Trail', 'nature_walk', 'Wooden boat ride across Sumendu lake rowed by licensed resident boatmen, followed by a walk through village large-cardamom plantations.', 90, 350, 'walk_in', 'Mirik Boatmen & Farmers Union', 100, 'Morning (10:00 - 12:00)'),\n(24, 'Makaibari Women Homestay & Biodynamic Tea Rolling Experience', 'homestay', 'Spend an afternoon inside a tea-picker family cottage learning biodynamic agricultural lore, hand-sorting tea, and enjoying a home meal.', 150, 700, 'prior_booking', 'Makaibari Women Homestay Association', 100, 'Afternoon (13:00 - 16:00)'),\n(25, 'Himalayan Ridge Paragliding & Indigenous Floriculture Nursery', 'adventure', 'Tandem paragliding flight over the Teesta valley followed by a visit to a village cactus and cymbidium orchid greenhouse.', 90, 2500, 'prior_booking', 'Kalimpong Adventure Pilots & Florists Guild', 90, 'Morning (09:00 - 11:30)');\n